/// Load and validate a `SeaSourceSet` through `domainforge-core`.
///
/// Verifies every source URI/hash, resolves imports from the supplied set,
/// enforces finite limits, and rejects unsupported DomainForge versions before
/// returning a `DomainModelRef`. No side effects.
//
// Import resolution uses the pinned library's public parse API
// (`parse_source`) to parse every file in-memory, then validates namespace
// references and exports adapter-side. This achieves semantic parity with the
// library's own ModuleResolver (which is filesystem-based and cannot accept an
// in-memory source set) without staging temp files or calling a CLI.
pub fn load_validate(source_set: &SeaSourceSet) -> Result<DomainModel, ForgeError> {
    // ── Version check ──
    if domainforge_core::VERSION != EXPECTED_DOMAINFORGE_VERSION {
        return Err(domain_model_error(format!(
            "unsupported DomainForge version: expected={EXPECTED_DOMAINFORGE_VERSION} linked={}",
            domainforge_core::VERSION
        )));
    }

    // ── Finite limits: source count ──
    if source_set.files.len() > MAX_SOURCE_COUNT {
        return Err(domain_model_error(format!(
            "source count {} exceeds limit {MAX_SOURCE_COUNT}",
            source_set.files.len()
        )));
    }

    // ── URI validation + duplicate detection + aggregate bytes ──
    let mut seen_uris = HashSet::new();
    let mut total_bytes = 0usize;
    for file in &source_set.files {
        if file.uri.is_empty() {
            return Err(domain_model_error("source URI must not be empty".into()));
        }
        if file.uri.starts_with('/') {
            return Err(domain_model_error(format!(
                "absolute URI rejected: {}",
                file.uri
            )));
        }
        if file.uri.split('/').any(|component| component == "..") {
            return Err(domain_model_error(format!(
                "traversal URI rejected: {}",
                file.uri
            )));
        }
        if !seen_uris.insert(&file.uri) {
            return Err(domain_model_error(format!(
                "duplicate source URI: {}",
                file.uri
            )));
        }
        total_bytes += file.content.len();
    }
    if total_bytes > MAX_AGGREGATE_BYTES {
        return Err(domain_model_error(format!(
            "aggregate bytes {total_bytes} exceeds limit {MAX_AGGREGATE_BYTES}"
        )));
    }

    // ── Hash verification for ALL files (not just entry) ──
    for file in &source_set.files {
        let computed = sha256_content(&file.content);
        if computed != file.sha256 {
            return Err(domain_model_error(format!(
                "source hash drift for {}: declared={} computed={computed}",
                file.uri, file.sha256
            )));
        }
    }

    // ── Find entry source ──
    let entry = source_set
        .files
        .iter()
        .find(|f| f.uri == source_set.entry_uri)
        .ok_or_else(|| ForgeError::Input("entry source not found in source set".into()))?;

    // ── Parse all files in-memory ──
    let mut asts: HashMap<&str, _> = HashMap::new(); // uri → ast
    let mut ns_to_uri: HashMap<&str, &str> = HashMap::new(); // namespace → uri
    let mut total_ast_nodes = 0usize;
    for file in &source_set.files {
        let ast = parse_source(&file.content).map_err(|e| {
            domain_model_error(format!("parse failed for {}: {e}", file.uri))
        })?;
        if let Some(ns) = &ast.metadata.namespace {
            if ns_to_uri.insert(ns.as_str(), file.uri.as_str()).is_some() {
                return Err(domain_model_error(format!(
                    "duplicate namespace '{ns}' declared by multiple files"
                )));
            }
        }
        total_ast_nodes += ast.declarations.len();
        asts.insert(file.uri.as_str(), ast);
    }
    if total_ast_nodes > MAX_AST_NODES {
        return Err(domain_model_error(format!(
            "AST node count {total_ast_nodes} exceeds limit {MAX_AST_NODES}"
        )));
    }

    // ── Resolve imports from the supplied set ──
    resolve_imports(&source_set.files, &asts, &ns_to_uri)?;

    // ── Build graph from entry AST (same as pinned library behavior) ──
    let options = ParseOptions::default();
    let entry_ast = asts
        .get(entry.uri.as_str())
        .expect("entry parsed above");
    let graph = parse_to_graph_with_options(&entry.content, &options)
        .map_err(|e| domain_model_error(format!("graph build failed: {e}")))?;

    // ── Semantic validation ──
    let validation = graph.validate();
    if validation.error_count > 0 {
        let errors: Vec<String> = validation
            .violations
            .iter()
            .filter(|v| v.severity == Severity::Error)
            .map(|v| format!("{}: {}", v.policy_name, v.message))
            .collect();
        return Err(domain_model_error(format!(
            "semantic validation failed: {}",
            errors.join("; ")
        )));
    }

    // ── Build source_refs (sorted, all verified files) ──
    let mut source_refs: Vec<SourceRef> = source_set
        .files
        .iter()
        .map(|f| SourceRef {
            uri: f.uri.clone(),
            sha256: f.sha256.clone(),
        })
        .collect();
    source_refs.sort();

    // ── Build parse_options_sha256 (includes version + limits) ──
    let parse_options_value = serde_json::json!({
        "namespace_registry": null,
        "entry_path": source_set.entry_uri,
        "domainforge_version": domainforge_core::VERSION,
        "limits": {
            "max_source_count": MAX_SOURCE_COUNT,
            "max_aggregate_bytes": MAX_AGGREGATE_BYTES,
            "max_import_depth": MAX_IMPORT_DEPTH,
            "max_ast_nodes": MAX_AST_NODES,
        }
    });
    let parse_options_sha256 = sha256_json(&parse_options_value)?;

    // ── Build semantic_model_sha256 over the canonical 4-tuple ──
    let canonical_tuple = serde_json::json!({
        "domainforge_version": domainforge_core::VERSION,
        "adapter_descriptor_sha256": ADAPTER_DESCRIPTOR_SHA256,
        "parse_options_sha256": parse_options_sha256,
        "source_refs": source_refs,
    });
    let semantic_model_sha256 = sha256_json(&canonical_tuple)?;

    // ── Extract concept refs from the graph (sorted) ──
    let mut concept_refs: Vec<String> = graph
        .all_entities()
        .iter()
        .map(|e| e.name().to_string())
        .collect();
    concept_refs.extend(graph.all_resources().iter().map(|r| r.name().to_string()));
    concept_refs.sort();
    concept_refs.dedup();
    let mut class_refs: Vec<String> = graph
        .all_resources()
        .iter()
        .map(|resource| resource.name().to_string())
        .collect();
    class_refs.sort();
    class_refs.dedup();

    let model_ref = DomainModelRef {
        source_refs,
        domainforge_version: domainforge_core::VERSION.to_string(),
        adapter_descriptor_sha256: ADAPTER_DESCRIPTOR_SHA256.into(),
        parse_options_sha256,
        semantic_model_sha256,
        concept_refs,
        class_refs,
        validation_evidence_refs: vec![format!(
            "validation:error_count={}",
            validation.error_count
        )],
    };

    Ok(DomainModel { graph, model_ref })
}

fn domain_model_error(message: String) -> ForgeError {
    ForgeError::Internal(format!("domain_model_error: {message}"))
}

/// Validate that every import in every file resolves to a namespace declared by
/// a file in the set (or `std`/`std:*`). Detects cycles and unexported named
/// imports. Semantic parity with domainforge-core's ModuleResolver but in-memory.
fn resolve_imports(
    files: &[SourceFile],
    asts: &HashMap<&str, domainforge_core::parser::ast::Ast>,
    ns_to_uri: &HashMap<&str, &str>,
) -> Result<(), ForgeError> {
    // Collect exports per namespace.
    let mut ns_exports: HashMap<&str, HashSet<String>> = HashMap::new();
    for file in files {
        let ast = &asts[file.uri.as_str()];
        let ns = ast.metadata.namespace.as_deref().unwrap_or("");
        let exports = collect_exports(ast);
        ns_exports.insert(ns, exports);
    }

    for file in files {
        let ast = &asts[file.uri.as_str()];
        for import in &ast.metadata.imports {
            let module = &import.from_module;
            if module == "std" || module.starts_with("std:") {
                continue;
            }
            let Some(dep_ns) = ns_to_uri.get(module.as_str()).map(|_| module.as_str()) else {
                return Err(domain_model_error(format!(
                    "unresolved import: namespace '{module}' not in source set (in {})",
                    file.uri
                )));
            };
            // Check named imports exist in the dependency's exports.
            if let ImportSpecifier::Named(items) = &import.specifier {
                let exports = ns_exports.get(dep_ns).cloned().unwrap_or_default();
                for item in items {
                    if !exports.contains(&item.name) {
                        return Err(domain_model_error(format!(
                            "import error: '{}' is not exported by namespace '{}' (in {})",
                            item.name, module, file.uri
                        )));
                    }
                }
            }
        }
    }

    // Cycle detection over the import graph.
    let mut visited = HashSet::new();
    let mut stack = Vec::new();
    for file in files {
        let ast = &asts[file.uri.as_str()];
        let file_ns = ast.metadata.namespace.as_deref().unwrap_or("");
        if !file_ns.is_empty() {
            detect_cycle(file_ns, ns_to_uri, asts, &mut visited, &mut stack, MAX_IMPORT_DEPTH)?;
        }
    }
    Ok(())
}

fn detect_cycle(
    ns: &str,
    ns_to_uri: &HashMap<&str, &str>,
    asts: &HashMap<&str, domainforge_core::parser::ast::Ast>,
    visited: &mut HashSet<String>,
    stack: &mut Vec<String>,
    depth_left: usize,
) -> Result<(), ForgeError> {
    if depth_left == 0 {
        return Err(domain_model_error(format!(
            "import depth exceeds limit {MAX_IMPORT_DEPTH}"
        )));
    }
    if stack.contains(&ns.to_string()) {
        let cycle = stack.join(" → ") + " → " + ns;
        return Err(domain_model_error(format!("circular import: {cycle}")));
    }
    if visited.contains(ns) {
        return Ok(());
    }
    visited.insert(ns.to_string());
    stack.push(ns.to_string());

    let Some(&uri) = ns_to_uri.get(ns) else {
        stack.pop();
        return Ok(());
    };
    let ast = &asts[uri];
    for import in &ast.metadata.imports {
        let dep = &import.from_module;
        if dep == "std" || dep.starts_with("std:") {
            continue;
        }
        detect_cycle(dep, ns_to_uri, asts, visited, stack, depth_left - 1)?;
    }
    stack.pop();
    Ok(())
}

/// Extract exported declaration names from an AST (mirrors domainforge-core's collect_exports).
fn collect_exports(ast: &domainforge_core::parser::ast::Ast) -> HashSet<String> {
    let mut exports = HashSet::new();
    for node in &ast.declarations {
        if let AstNode::Export(inner) = &node.node {
            if let Some(name) = declaration_name(&inner.node) {
                exports.insert(name.to_string());
            }
        }
    }
    exports
}

fn declaration_name(node: &AstNode) -> Option<&str> {
    match node {
        AstNode::Entity { name, .. }
        | AstNode::Resource { name, .. }
        | AstNode::Flow {
            resource_name: name,
            ..
        }
        | AstNode::Pattern { name, .. }
        | AstNode::Role { name, .. }
        | AstNode::Relation { name, .. }
        | AstNode::Dimension { name } => Some(name),
        _ => None,
    }
}

